/** Writes src/app/styles/tokens.css from @smartwear/design-tokens — the only source of colours, type and spacing. */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { cssVariablesBlock } from '@smartwear/design-tokens/css';
import { tailwindThemeBlock } from '@smartwear/design-tokens/tailwind';

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'app', 'styles', 'tokens.css');
const css = [
  '/* GENERATED by scripts/gen-theme.ts from packages/design-tokens — do not edit. */',
  cssVariablesBlock('light', ':root'),
  '@media (prefers-color-scheme: dark) {',
  cssVariablesBlock('dark', ':root:not([data-theme="light"])'),
  '}',
  // Scoped too, so any subtree can opt into a theme (e.g. the ink brand panel on the sign-in page).
  cssVariablesBlock('dark', '[data-theme="dark"]'),
  cssVariablesBlock('light', '[data-theme="light"]'),
  // Drop Tailwind's default palette and fonts: only SmartWear tokens exist, so a stray `bg-red-500` can't compile.
  '@theme { --color-*: initial; --font-*: initial; }',
  tailwindThemeBlock(),
  '',
].join('\n');
writeFileSync(out, css);
console.log('wrote', out);
